    # 2. Word tokens and stem check (e.g. grocery -> groceries)
    words = [w for w in re.split(r"\W+", clean_q) if len(w) > 2]
    for t in tasks:
        t_title = t.title.lower()
        for w in words:
            if w in t_title:
                return t
            # Stem check (strip 'ies', 'ing', 'ed', 's', 'y')
            stem = w.rstrip("s").rstrip("y")
